// 一次性构建脚本：把 textures/*.jpg 转成 base64 内嵌到 textures.js（离线可用、零 CORS 风险）
// 用法：node tools/build-textures.js
const fs = require('fs');
const path = require('path');

const files = {
  metal: path.join(__dirname, '..', 'textures', 'metal.jpg'),
  wood: path.join(__dirname, '..', 'textures', 'wood.jpg'),
  brick: path.join(__dirname, '..', 'textures', 'brick.jpg'),
  concrete: path.join(__dirname, '..', 'textures', 'concrete.jpg'),
  crateWood: path.join(__dirname, '..', 'textures', 'crate_wood.jpg'),
};

const parts = [];
parts.push('// textures.js —— 联网下载的 CC0 贴图（Poly Haven），base64 内嵌，离线可用');
parts.push('// 由 tools/build-textures.js 生成，请勿手改');
parts.push('window.TEX = window.TEX || {};');
for (const [key, file] of Object.entries(files)) {
  if (!fs.existsSync(file)) { console.warn('missing', file); continue; }
  const b64 = fs.readFileSync(file).toString('base64');
  parts.push(`window.TEX.${key} = "data:image/jpeg;base64,${b64}";`);
}
const out = parts.join('\n') + '\n';
const dest = path.join(__dirname, '..', 'textures.js');
fs.writeFileSync(dest, out);
console.log('wrote', dest, (out.length / 1024).toFixed(1) + ' KB');
